def translate_existing_menu(apps, schema_editor):
    Card = apps.get_model('quickstart', 'Card')
    cards = Card.objects.using(schema_editor.connection.alias)
    updates = []
    for card in cards.filter(description_en='').exclude(descripcion__isnull=True).only('id', 'descripcion'):
        translation = TRANSLATIONS.get(card.descripcion.strip())
        if translation:
            card.description_en = translation
            updates.append(card)
    cards.bulk_update(updates, ['description_en'], batch_size=200)


class Migration(migrations.Migration):
    dependencies = [('quickstart', '0023_order_dispatch_and_english_descriptions')]
    operations = [migrations.RunPython(translate_existing_menu, migrations.RunPython.noop)]
